/**
 * Writes scripts/data/hematology-market-research-saudi-arabia.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-hematology-ksa-research-cover.mjs.
 *
 *   node scripts/generate-hematology-ksa-research-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/hematology-market-research-saudi-arabia.json');

export const MARTHA_DEVITO_SANITY_ID = '6263dcc8-994f-4cd1-9228-7e92332659d3';

/** Every blogPost field that applies to a healthcare-silo article. */
export const HEMATOLOGY_KSA_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-hematology-market-research-saudi-arabia.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.HEMATOLOGY_KSA_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.HEMATOLOGY_KSA_BODY_HTML.split('<h2')[0])
    .replace(/^Hematology market research Saudi Arabia[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.HEMATOLOGY_KSA_META_TITLE,
      metaDescription: mod.HEMATOLOGY_KSA_META_DESCRIPTION,
      focusKeyword: 'hematology market research Saudi Arabia',
      keywords: [
        'hematology market research Saudi Arabia',
        'sickle cell thalassemia market Saudi Arabia',
        'Casgevy Saudi Arabia',
        'sickle cell gene therapy Saudi Arabia',
        'thalassemia market research Saudi Arabia',
        'SFDA Casgevy',
        'hydroxyurea Saudi Arabia',
        'hematology market access Saudi Arabia',
      ],
      canonicalUrl: mod.HEMATOLOGY_KSA_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.HEMATOLOGY_KSA_META_TITLE,
      ogDescription: mod.HEMATOLOGY_KSA_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.HEMATOLOGY_KSA_COVER_IMAGE}`,
        alt: mod.HEMATOLOGY_KSA_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.HEMATOLOGY_KSA_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.HEMATOLOGY_KSA_SLUG },
    excerpt: mod.HEMATOLOGY_KSA_EXCERPT,
    publishedAt: mod.HEMATOLOGY_KSA_PUBLISHED_ISO,
    updatedAt: mod.HEMATOLOGY_KSA_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: MARTHA_DEVITO_SANITY_ID,
      name: 'Martha DeVito',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.HEMATOLOGY_KSA_HERO_IMAGE}`,
      alt: mod.HEMATOLOGY_KSA_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for hematology market research Saudi Arabia',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.HEMATOLOGY_KSA_TAGS],
    country: 'Saudi Arabia',
    language: 'en',
    readingTime: mod.HEMATOLOGY_KSA_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.HEMATOLOGY_KSA_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.HEMATOLOGY_KSA_EXECUTIVE_SUMMARY_HTML}\n\n${mod.HEMATOLOGY_KSA_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What hematology market research Saudi Arabia should measure',
        type: 'table',
        data: JSON.stringify(
          mod.HEMATOLOGY_KSA_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'Aljabry et al., 2024; Alsaffar et al., 2024; Al-Jefri et al., 2025; Vertex / SFDA 2024',
      },
      portableText(
        firstParagraph ||
          'Hematology market research Saudi Arabia is a launch and access problem before it is a sizing problem.',
      ),
    ],
    faq: mod.HEMATOLOGY_KSA_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: ['who-does-obesity-market-research-saudi-arabia', 'gcc-pharmacoeconomics'],
    ctaSection: { ...mod.HEMATOLOGY_KSA_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.HEMATOLOGY_KSA_BODY_HTML),
    factCheckedAt: mod.HEMATOLOGY_KSA_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/hematology-market-research-saudi-arabia-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of HEMATOLOGY_KSA_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
